import {Port,materials} from '../../core/index.js';
import {portQuaternion} from '../../modeling/parts.js';
import {THREE,box} from './geometry.js';
import {spec} from './dimensions.js';
export function socketPose(cfg){return portQuaternion(cfg.face??'front').premultiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,0,1),cfg.turn??0));}
export function contactDrills(){const holes=[];for(const cfg of spec.outputs){const q=socketPose(cfg);for(let i=0;i<4;i++){const v=new THREE.Vector3((i-1.5)*2,-6.4,-.6).applyQuaternion(q).add(new THREE.Vector3(...cfg.position));holes.push({id:cfg.id,pin:i+1,x:v.x,y:v.y});}}for(let i=0;i<4;i++)holes.push({id:'grove',pin:i+1,x:-(i-1.5)*2,y:-15.7});return holes;}
function socket(host,cfg){const input=cfg.id==='grove',depth=input?7.8:6,frame=new THREE.Group();frame.name='Original PbHub '+cfg.id+' actual receiving assembly';frame.position.fromArray(cfg.position);frame.quaternion.copy(socketPose(cfg));host.body.add(frame);const plastic=materials.plastic(input?0xb62c3a:0x171a18,{roughness:.7}),tin=materials.metal(0xb5b49f,{roughness:.43}),parts=[],walls=[],rails=[],contacts=[],returns=[],feet=[],tails=[],b=(s,p,n,m=plastic)=>{const o=box(frame,s,p,m,'PbHub '+cfg.id+' '+n);parts.push(o);return o;};
 for(const sign of[-1,1]){walls.push(b([.7,depth,5.2],[sign*4.65,-depth/2,0],'real receiving side wall'));rails.push(b([.7,depth,.65],[sign*3.95,-depth/2,2.275],'actual retaining rail'));}const floor=b([8.6,depth,.6],[0,-depth/2,-2.3],'real receiving floor'),back=b([8.6,.65,4.6],[0,-depth+.325,.3],'real recessed insertion stop'),latch=b([3.8,1.25,.5],[0,-depth+.2+1.25,2.25],'real fixed retaining bridge');
 for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(b([.42,input?5.8:4.7,.42],[x,input?-4:-3.05,-.6],'retained mating contact '+(i+1),tin));if(input){returns.push(b([.42,.6,2.2],[x,-7.2,-1.5],'right-angle return '+(i+1),tin));feet.push(b([.42,1.4,.42],[x,-7.8,-2.4],'physical foot '+(i+1),tin));tails.push(b([.42,.42,2.5],[x,-8.3,-1.3],'throughPCB retained tail '+(i+1),tin));}else{tails.push(b([.42,1.7,.42],[x,-6.05,-.6],'vertical retained throughPCB stem '+(i+1),tin));feet.push(b([.75,.2,.75],[x,-6.9,-.6],'physical rear solder joint '+(i+1),tin));}}
 const seat=input?b([8.6,1.2,.8],[0,-8.1,0],'deep support seatsPCB'):b([8.6,.45,4.6],[0,-5.775,0],'actual PCB carrier foot'),names=input?spec.input.pins:['IN'+cfg.channel,'OUT'+cfg.channel,'5V','GND'],port=host.add(new Port({id:cfg.id,label:input?'Original PbHub PORT.A I2C upstream':'Original PbHub CH'+cfg.channel+' PORT.B',connector:'grove',position:cfg.position,quaternion:socketPose(cfg),hitSize:[10,1,5.2],pins:names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.6],order:col=>col+1},meta:{role:'visual-connector',face:input?'bottom':'front',channel:input?null:cfg.channel,scope:'Original U041 physical four-contact receiver only;no GPIO/ADC/PWM/RGB/I2C/address/MCU/power behavior'}}));return{frame,parts,walls,rails,floor,back,latch,seat,contacts,returns,feet,tails,port,input};
}
export function groves(host){return[socket(host,{...spec.input}),...spec.outputs.map(c=>socket(host,{...c,face:'front'}))];}
